package com.vandorlabs.neoforge.navigation.observer;
import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.material.MapColor;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.registries.RegisterEvent;
@EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)
public final class NativeObserverBindings {
 public static final Map<String,NativeObserverCoreBlock> CORES=new LinkedHashMap<>();public static NativeObserverPartBlock PART;public static BlockEntityType<NativeObserverEntity> ENTITY;public static BlockEntityType<NativeObserverPartEntity> PART_ENTITY;public static MenuType<NativeObserverMenu> MENU;
 private static ResourceLocation id(String s){return ResourceLocation.fromNamespaceAndPath("vandorlabs",s);}
 @SubscribeEvent public static void register(RegisterEvent e){e.register(Registries.BLOCK,h->{for(var d:NativeObserverDesigns.ALL){var b=new NativeObserverCoreBlock(d,BlockBehaviour.Properties.of().mapColor(MapColor.METAL).strength(5,6).requiresCorrectToolForDrops().noOcclusion().sound(SoundType.METAL));CORES.put(d.id(),b);h.register(id(d.block()),b);}PART=new NativeObserverPartBlock(BlockBehaviour.Properties.of().strength(5,6).noOcclusion().noLootTable());h.register(id("observer_part"),PART);});e.register(Registries.ITEM,h->{for(var d:NativeObserverDesigns.ALL)h.register(id(d.block()),new BlockItem(CORES.get(d.id()),new Item.Properties()));});e.register(Registries.BLOCK_ENTITY_TYPE,h->{ENTITY=BlockEntityType.Builder.of(NativeObserverEntity::new,CORES.values().toArray(Block[]::new)).build(null);PART_ENTITY=BlockEntityType.Builder.of(NativeObserverPartEntity::new,PART).build(null);h.register(id("observer_core"),ENTITY);h.register(id("observer_part"),PART_ENTITY);NativeObserverTransactions.register();});e.register(Registries.MENU,h->{MENU=net.neoforged.neoforge.common.extensions.IMenuTypeExtension.create((window,inventory,buffer)->new NativeObserverMenu(MENU,window,inventory,buffer.readBlockPos(),buffer.readBlockPos()));h.register(id("observer"),MENU);});}
 @SubscribeEvent public static void powerCapabilities(net.neoforged.neoforge.capabilities.RegisterCapabilitiesEvent event){
  var energy=net.neoforged.neoforge.capabilities.Capabilities.EnergyStorage.BLOCK;
  event.registerBlockEntity(energy,ENTITY,NativeObserverEntity::powerInput);
  event.registerBlockEntity(energy,PART_ENTITY,NativeObserverPartEntity::powerInput);
 }
 /** An inlet consumes energy on the physical footprint without retaining a network. */
 public static boolean nativeInlet(Object capability){return capability instanceof NativeObserverEntity.Input;}
 @SubscribeEvent public static void aliases(net.neoforged.neoforge.registries.ModifyRegistriesEvent e){for(var entry:Map.of("survey_dish_core","standalone_dish_core","sentinel_array_core","standalone_antenna_core").entrySet()){e.getRegistry(Registries.BLOCK).addAlias(id(entry.getKey()),id(entry.getValue()));e.getRegistry(Registries.ITEM).addAlias(id(entry.getKey()),id(entry.getValue()));}}
 @SubscribeEvent public static void creative(net.neoforged.neoforge.event.BuildCreativeModeTabContentsEvent e){if(e.getTabKey().location().equals(id("vandorlabs")))for(var b:CORES.values())e.accept(b);}
 @SubscribeEvent public static void payload(net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent e){NativeObserverPayload.register(e);}
 public static NativeObserverEntity ownerAt(Level l,BlockPos p){if(!NativeObserverFormation.loaded(l,p))return null;var raw=l.getBlockEntity(p);return raw instanceof NativeObserverEntity owner?owner:raw instanceof NativeObserverPartEntity part?part.root():null;}
 public static boolean open(Player p,Level l,BlockPos pos){var owner=ownerAt(l,pos);if(owner==null||!NativeObserverAccess.canUse(p,owner,pos)||MENU==null)return false;if(p instanceof ServerPlayer actor){actor.connection.send(owner.getUpdatePacket());actor.openMenu(new SimpleMenuProvider((window,inventory,ignored)->new NativeObserverMenu(MENU,window,owner,pos),owner.getBlockState().getBlock().getName()),buffer->{buffer.writeBlockPos(owner.getBlockPos());buffer.writeBlockPos(pos);});}return true;}
 public static boolean interact(Player p,Level l,BlockPos pos,InteractionHand hand){var t=ownerAt(l,pos);if(t==null||!NativeObserverAccess.canUse(p,t,pos))return false;if(l.isClientSide)return true;if(!(p instanceof ServerPlayer actor))return false;try{if(!t.formed())return NativeObserverTransactions.request(t,actor,true,pos);if(p.isShiftKeyDown())return NativeObserverTransactions.request(t,actor,false,pos);return open(p,l,pos);}catch(IllegalArgumentException refused){p.displayClientMessage(net.minecraft.network.chat.Component.literal(refused.getMessage()),true);return true;}}
 private NativeObserverBindings(){}
}